insert into basket_site_theme (
    theme_name, description, bg_color, bg_image_file_id, mobile_bg_image_file_id, bg_display,
    colors_json, draft_json, has_draft, theme_status, version_no, update_by, create_time, update_time, is_delete
) values (
    #{themeName}, #{description}, #{bgColor}, #{bgImageFileId}, #{mobileBgImageFileId}, #{bgDisplay},
    #{colorsJson}, #{draftJson}, #{hasDraft}, #{themeStatus}, #{versionNo}, #{updateBy}, #{createTime}, #{updateTime}, #{isDelete}
)

insert into basket_site_theme_binding (
    scope_type, scope_id, theme_id, theme_version, active_key, update_by, create_time, update_time, is_delete
) values (
    #{scopeType}, #{scopeId}, #{themeId}, #{themeVersion}, #{activeKey}, #{updateBy}, #{createTime}, #{updateTime}, 0
)
